from stage import Game, Sprite, Box

game = Game(width=480, height=360, background="#0B1020")

ground = Box(x=0, y=320, width=480, height=40, color="#1F7A5C", name="ground")
platform = Box(x=160, y=200, width=160, height=16, color="#3FBF7F", name="platform")

player = Sprite("frog", x=240, y=60, size=40, name="player")
player.vy = 0


@game.every_frame
def update():
    if game.key_down("left"):
        player.x = player.x - 4
    if game.key_down("right"):
        player.x = player.x + 4

    if game.key_down("up") and player.y >= 300:
        player.vy = -14

    player.vy = player.vy + 1
    player.y = player.y + player.vy

    if player.touching(platform) and player.vy > 0:
        player.y = platform.y - 20
        player.vy = 0

    if player.y > 300:
        player.y = 300
        player.vy = 0


game.start()

from stage import Game, Sprite, Text, random_number

game = Game(width=480, height=360, background="#0B1020")

player = Sprite("robot", x=240, y=180, size=40, name="player")

gems = []
for i in range(5):
    gem = Sprite("gem", x=random_number(20, 460), y=random_number(20, 340),
                 size=26, name="gem" + str(i))
    gems.append(gem)

game.score = 0
label = Text("Gems: 0", x=16, y=16, size=20, color="#FFC93C")


@game.every_frame
def update():
    if game.key_down("left"):
        player.x = player.x - 4
    if game.key_down("right"):
        player.x = player.x + 4
    if game.key_down("up"):
        player.y = player.y - 4
    if game.key_down("down"):
        player.y = player.y + 4
    game.clamp_inside(player)

    for gem in gems:
        if player.touching(gem):
            gem.remove()
            game.score = game.score + 1
            label.words = "Gems: " + str(game.score)


game.start()

